#!/data/data/com.termux/files/usr/bin/bash
set -e

# SIGMA 5 — single-file Termux installer
# This file contains the complete project source, package manifest,
# verification files, README/command list, and both banner images.
# It reconstructs the project in ~/SIGMA5_WHATSAPP_TELEGRAM_BOT.

TELEGRAM_BOT_TOKEN=""
TELEGRAM_CHAT_ID=""

PROJECT="$HOME/SIGMA5_WHATSAPP_TELEGRAM_BOT"
mkdir -p "$PROJECT/assets" "$PROJECT/session"
cd "$PROJECT"

echo "== SIGMA 5: writing complete project =="

cat > package.json <<'__SIGMA5_package_json__'
{
  "name": "sigma5-whatsapp-telegram-bot",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "description": "SIGMA 5 WhatsApp bot with Telegram control and 150 registered commands.",
  "scripts": {
    "start": "node index.mjs",
    "verify": "node verify.mjs",
    "check": "node --check index.mjs"
  },
  "engines": {
    "node": ">=20.0.0"
  },
  "dependencies": {
    "@hapi/boom": "^9.1.3",
    "@whiskeysockets/baileys": "7.0.0-rc14",
    "dotenv": "^16.6.1",
    "pino": "^9.6.0",
    "telegraf": "^4.16.3"
  }
}
__SIGMA5_package_json__
cat > .env.example <<'__SIGMA5__env_example__'
# Telegram credentials — PRIMARY
TELEGRAM_BOT_TOKEN=
TELEGRAM_CHAT_ID=

# Telegram credentials — BACKUP (used only if PRIMARY is blank)
TELEGRAM_BOT_TOKEN_2=
TELEGRAM_CHAT_ID_2=

OWNER_NAME=SIGMA 5
OWNER_NUMBER=
PREFIX=.
PAIRING_NUMBER=

__SIGMA5__env_example__
cat > .env <<__SIGMA5__env__
TELEGRAM_BOT_TOKEN=$TELEGRAM_BOT_TOKEN
TELEGRAM_CHAT_ID=$TELEGRAM_CHAT_ID
TELEGRAM_BOT_TOKEN_2=
TELEGRAM_CHAT_ID_2=
OWNER_NAME=SIGMA 5
OWNER_NUMBER=
PREFIX=.
PAIRING_NUMBER=
__SIGMA5__env__
cat > .gitignore <<'__SIGMA5__gitignore__'
node_modules/
.env
session/
*.log

__SIGMA5__gitignore__
cat > index.mjs <<'__SIGMA5_index_mjs__'
import 'dotenv/config';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import pino from 'pino';
import { Boom } from '@hapi/boom';
import makeWASocket, {
  Browsers, DisconnectReason, useMultiFileAuthState, makeCacheableSignalKeyStore
} from '@whiskeysockets/baileys';
import { Telegraf, Input } from 'telegraf';
import { COMMANDS } from './commands.mjs';

const ROOT = process.cwd();
const cfg = {
  token: process.env.TELEGRAM_BOT_TOKEN || process.env.TELEGRAM_BOT_TOKEN_2 || '',
  chatId: process.env.TELEGRAM_CHAT_ID || process.env.TELEGRAM_CHAT_ID_2 || '',
  owner: process.env.OWNER_NUMBER || '',
  ownerName: process.env.OWNER_NAME || 'SIGMA 5',
  prefix: process.env.PREFIX || '.',
  pairingNumber: process.env.PAIRING_NUMBER || ''
};
const ASSETS = {
  banner: path.join(ROOT,'assets','whatsapp-banner.png'),
  activation: path.join(ROOT,'assets','telegram-activation.png')
};
const log = pino({level: process.env.LOG_LEVEL || 'info'});
const state = { sock:null, telegram:null, maintenance:false, audit:[], warnings:new Map(),
  groups:new Map(), allow:new Set(cfg.owner ? [digits(cfg.owner)] : []), pairRequests:new Set() };

function digits(v=''){return String(v).replace(/\D/g,'')}
function numberOf(j=''){return j.split('@')[0].replace(/:\d+$/,'')}
function isGroup(j=''){return j.endsWith('@g.us')}
function textOf(m){const x=m.message||{};return x.conversation||x.extendedTextMessage?.text||x.imageMessage?.caption||x.videoMessage?.caption||''}
function senderOf(m){return m.key.participant||m.key.remoteJid||''}
function argsOf(s){return s.trim().split(/\s+/).filter(Boolean)}
function argText(s){return s.trim().split(/\s+/).slice(1).join(' ')}
function owner(j){return Boolean(cfg.owner&&digits(cfg.owner)===numberOf(j))||state.allow.has(numberOf(j))}
function uptime(){let s=Math.floor(process.uptime()),d=Math.floor(s/86400);s%=86400;let h=Math.floor(s/3600);s%=3600;let m=Math.floor(s/60),x=s%60;return `${d}d ${h}h ${m}m ${x}s`}
function groupCfg(j){if(!state.groups.has(j))state.groups.set(j,{antilink:false,antispam:false,rules:'Be respectful. No spam, scams or unwanted links.'});return state.groups.get(j)}
function audit(a,j,u){state.audit.push({t:new Date().toISOString(),a,j,u});if(state.audit.length>200)state.audit.shift()}
function clean(s=''){return String(s).replace(/\0/g,'').slice(0,60000)}
function link(s=''){return /(https?:\/\/|www\.|t\.me\/|wa\.me\/|bit\.ly\/|tinyurl\.com\/)/i.test(s)}
function spam(s=''){return /(.)\1{14,}|(.)\2{5,}/u.test(s)}
async function send(j,text,extra={}){return state.sock.sendMessage(j,{text:clean(text),...extra})}
async function banner(j,caption){return state.sock.sendMessage(j,{image:fs.readFileSync(ASSETS.banner),caption:clean(caption).slice(0,1024)})}
function menu(){return menuParts(60000).join('\n')}
function menuParts(limit=3800){
  const b={};for(const c of COMMANDS)(b[c.category]??=[]).push(c);
  const blocks=[`╭━━〔 SIGMA 5 〕━━╮\n┃ 150 COMMANDS\n╰━━━━━━━━━━━━━━━━╯`];
  for(const [k,v] of Object.entries(b)){blocks.push(`╭─〔 ${k} 〕\n${v.map(c=>`│ ${cfg.prefix}${c.name} — ${c.description}`).join('\n')}\n╰──────────────`)}
  const out=[];let cur='';
  for(const block of blocks){const candidate=cur?`${cur}\n\n${block}`:block;if(candidate.length>limit){if(cur)out.push(cur);cur=block;}else cur=candidate;}
  if(cur)out.push(cur);
  return out;
}
async function sendFullMenu(j){await banner(j,'🐺 SIGMA 5 • COMMAND MENU');for(const part of menuParts(60000))await send(j,part)}
function quoted(m){return m.message?.extendedTextMessage?.contextInfo?.quotedMessage}
function target(m,args){const q=m.message?.extendedTextMessage?.contextInfo?.participant;if(q)return q;const n=digits(args[0]||'');return n?`${n}@s.whatsapp.net`:''}
async function isAdmin(j,u){try{const m=await state.sock.groupMetadata(j);const target=numberOf(u);return !!m.participants.find(p=>numberOf(p.id)===target)?.admin}catch{return false}}
async function botAdmin(j){return isAdmin(j,numberOf(state.sock.user?.id||''))}
function basicEval(e){if(!/^[0-9+\-*/().%\s]+$/.test(e))throw Error('Only basic arithmetic is allowed.');const v=Function(`"use strict";return (${e})`)();if(!Number.isFinite(v))throw Error('Invalid result');return String(v)}
function nums(s){const a=s.split(/\s+/).map(Number);if(!a.length||a.some(Number.isNaN))throw Error('Use numbers separated by spaces');return a}

async function moderate(m,body){
  const j=m.key.remoteJid;if(!isGroup(j)||m.key.fromMe)return false;
  const s=groupCfg(j),u=senderOf(m);if(await isAdmin(j,u))return false;
  const reason=s.antilink&&link(body)?'link':s.antispam&&spam(body)?'spam':'';
  if(!reason)return false;
  try{
    await state.sock.sendMessage(j,{delete:m.key});
    if(await botAdmin(j)){await state.sock.groupParticipantsUpdate(j,[u],'remove');audit(`auto-${reason}`,j,u);await send(j,`🚫 Removed @${numberOf(u)} for ${reason}.`,{mentions:[u]})}
  }catch(e){log.warn({err:e},'moderation failed')}
  return true;
}

async function command(m){
  const j=m.key.remoteJid,body=textOf(m).trim(),u=senderOf(m);
  const normalized=body.toLowerCase();
  if(normalized==='menu'||normalized==='bot menu'||normalized===`${cfg.prefix}menu`)return sendFullMenu(j);
  if(!body.startsWith(cfg.prefix))return;
  const p=argsOf(body.slice(cfg.prefix.length)),c=p.shift()?.toLowerCase(),a=p;
  if(!c)return;
  if(state.maintenance&&!owner(u))return send(j,'🛠️ Maintenance mode is enabled.');
  if(c==='menu')return sendFullMenu(j);
  if(c==='ping')return send(j,`🏓 Pong • ${Math.round(Math.random()*99)+1} ms`);
  if(c==='help')return send(j,`Use ${cfg.prefix}menu to view all 150 commands.`);
  try{
    switch(c){
      case 'about':case 'botinfo':return send(j,`🐺 SIGMA 5\nCommands: ${COMMANDS.length}\nOwner: ${cfg.ownerName}`);
      case 'status':case 'session':return send(j,`WhatsApp: ${state.sock?.user?'CONNECTED':'DISCONNECTED'}\nUptime: ${uptime()}`);
      case 'uptime':return send(j,uptime());
      case 'time':return send(j,new Date().toLocaleTimeString());
      case 'date':return send(j,new Date().toLocaleDateString());
      case 'id':case 'jid':case 'groupid':return send(j,j);
      case 'owner':return send(j,`👑 ${cfg.ownerName}\nNumber configured: ${cfg.owner?'yes':'no'}`);
      case 'prefix':return send(j,cfg.prefix);
      case 'echo':case 'say':return send(j,argText(body)||'Nothing to echo.');
      case 'alive':return send(j,`✅ Online • ${uptime()}`);
      case 'upper':return send(j,argText(body).toUpperCase());
      case 'lower':return send(j,argText(body).toLowerCase());
      case 'reverse':return send(j,[...argText(body)].reverse().join(''));
      case 'length':return send(j,String([...argText(body)].length));
      case 'words':return send(j,String(argText(body).trim()?argText(body).trim().split(/\s+/).length:0));
      case 'lines':return send(j,String(argText(body).split('\n').length));
      case 'trim':return send(j,argText(body).trim());
      case 'title':return send(j,argText(body).toLowerCase().replace(/\b\w/g,x=>x.toUpperCase()));
      case 'slug':return send(j,argText(body).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''));
      case 'base64':return send(j,Buffer.from(argText(body)).toString('base64'));
      case 'unbase64':return send(j,Buffer.from(argText(body),'base64').toString());
      case 'repeat':{let n=Math.min(20,Math.max(1,Number(a[0]||1)));return send(j,(a.slice(1).join(' ')+'\n').repeat(n).slice(0,4000))}
      case 'char':{let i=Number(a[0]),t=a.slice(1).join(' ');return send(j,t[i]??'Out of range')}
      case 'replace':{let z=argText(body).split('|');return send(j,z.length>=3?z[0].replace(z[1],z.slice(2).join('|')):'Usage: .replace text|from|to')}
      case 'split':return send(j,argText(body).split(/\s+/).join('\n'));
      case 'calc':return send(j,basicEval(argText(body)));
      case 'sum':{let n=nums(argText(body));return send(j,String(n.reduce((x,y)=>x+y,0)))}
      case 'avg':{let n=nums(argText(body));return send(j,String(n.reduce((x,y)=>x+y,0)/n.length))}
      case 'min':return send(j,String(Math.min(...nums(argText(body)))));
      case 'max':return send(j,String(Math.max(...nums(argText(body)))));
      case 'abs':return send(j,String(Math.abs(Number(a[0]))));
      case 'round':return send(j,String(Math.round(Number(a[0]))));
      case 'floor':return send(j,String(Math.floor(Number(a[0]))));
      case 'ceil':return send(j,String(Math.ceil(Number(a[0]))));
      case 'sqrt':return send(j,String(Math.sqrt(Number(a[0]))));
      case 'pow':return send(j,String(Number(a[0])**Number(a[1])));
      case 'mod':return send(j,String(Number(a[0])%Number(a[1])));
      case 'percent':return send(j,String(Number(a[0])*Number(a[1])/100));
      case 'random':return send(j,String(1+Math.floor(Math.random()*100)));
      case 'dice':{let s=Math.max(2,Math.min(100,Number(a[0]||6)));return send(j,`🎲 ${1+Math.floor(Math.random()*s)}/${s}`)}
      case 'node':return send(j,process.version);
      case 'platform':return send(j,`${os.platform()} ${os.arch()}`);
      case 'memory':return send(j,`${(process.memoryUsage().rss/1048576).toFixed(1)} MB RSS`);
      case 'locale':return send(j,Intl.DateTimeFormat().resolvedOptions().locale);
      case 'timezone':return send(j,Intl.DateTimeFormat().resolvedOptions().timeZone);
      case 'now':return send(j,new Date().toISOString());
      case 'args':return send(j,JSON.stringify(a));
      case 'mention':return send(j,`Hello @${numberOf(u)}`,{mentions:[u]});
      case 'chat':return send(j,isGroup(j)?'GROUP':'PRIVATE');
      case 'private':return send(j,isGroup(j)?'❌ Group':'✅ Private');
      case 'group':return send(j,isGroup(j)?'✅ Group':'❌ Private');
      case 'features':return send(j,'Telegram control • pairing • 150 commands • moderation • SIGMA banner');
      case 'health':return send(j,`❤️ OK • WA ${state.sock?.user?'connected':'disconnected'} • ${uptime()}`);
      case 'env':return send(j,`Telegram token: ${cfg.token?'configured':'missing'}\nChat ID: ${cfg.chatId?'configured':'missing'}\nPrefix: ${cfg.prefix}`);
      case 'groupinfo':{if(!isGroup(j))return send(j,'Group only.');let m=await state.sock.groupMetadata(j);return send(j,`👥 ${m.subject}\nMembers: ${m.participants.length}`)}
      case 'admins':{if(!isGroup(j))return send(j,'Group only.');let m=await state.sock.groupMetadata(j),x=m.participants.filter(p=>p.admin);return send(j,x.map(p=>`@${numberOf(p.id)}`).join('\n')||'None',{mentions:x.map(p=>p.id)})}
      case 'members':{if(!isGroup(j))return send(j,'Group only.');let m=await state.sock.groupMetadata(j);return send(j,String(m.participants.length))}
      case 'groupname':{if(!isGroup(j))return send(j,'Group only.');let m=await state.sock.groupMetadata(j);return send(j,m.subject)}
      case 'setsubject':{if(!isGroup(j)||(!owner(u)&&!(await isAdmin(j,u))))return send(j,'Admin/owner only.');if(!(await botAdmin(j)))return send(j,'Bot must be admin.');await state.sock.groupUpdateSubject(j,a.join(' '));return send(j,'✅ Updated.')}
      case 'setdesc':{if(!isGroup(j)||(!owner(u)&&!(await isAdmin(j,u))))return send(j,'Admin/owner only.');if(!(await botAdmin(j)))return send(j,'Bot must be admin.');await state.sock.groupUpdateDescription(j,a.join(' '));return send(j,'✅ Updated.')}
      case 'link':{if(!isGroup(j)||(!owner(u)&&!(await isAdmin(j,u))))return send(j,'Admin/owner only.');if(!(await botAdmin(j)))return send(j,'Bot must be admin.');return send(j,`https://chat.whatsapp.com/${await state.sock.groupInviteCode(j)}`)}
      case 'revoke':{if(!isGroup(j)||(!owner(u)&&!(await isAdmin(j,u))))return send(j,'Admin/owner only.');if(!(await botAdmin(j)))return send(j,'Bot must be admin.');await state.sock.groupRevokeInvite(j);return send(j,'✅ Revoked.')}
      case 'promote':case 'demote':case 'kick':case 'add':{if(!isGroup(j)||(!owner(u)&&!(await isAdmin(j,u))))return send(j,'Admin/owner only.');if(!(await botAdmin(j)))return send(j,'Bot must be admin.');let t=target(m,a);if(!t)return send(j,`Usage: ${cfg.prefix}${c} <number>`);await state.sock.groupParticipantsUpdate(j,[t],c==='promote'?'promote':c==='demote'?'demote':c==='add'?'add':'remove');audit(c,j,u);return send(j,`✅ ${c}: @${numberOf(t)}`,{mentions:[t]})}
      case 'delete':{const q=m.message?.extendedTextMessage?.contextInfo;if(!q?.stanzaId)return send(j,'Reply to the message you want to delete.');const key={remoteJid:j,id:q.stanzaId,fromMe:numberOf(q.participant||'')===numberOf(state.sock.user?.id||''),participant:q.participant};if(!key.fromMe){key.fromMe=false;}await state.sock.sendMessage(j,{delete:key});return send(j,'🗑️ Deleted the replied message.')}
      case 'leave':if(!isGroup(j)||!owner(u))return send(j,'Owner only.');await state.sock.groupLeave(j);return;
      case 'tagall':{if(!isGroup(j))return send(j,'Group only.');let m=await state.sock.groupMetadata(j),ps=m.participants.map(p=>p.id);return send(j,a.join(' ')||'📣 Everyone',{mentions:ps})}
      case 'antilink':case 'antispam':{if(!isGroup(j)||(!owner(u)&&!(await isAdmin(j,u))))return send(j,'Admin/owner only.');let s=groupCfg(j);if(!a[0])return send(j,`${c}: ${s[c]?'ON':'OFF'}`);s[c]=a[0].toLowerCase()==='on';return send(j,`🛡️ ${c}: ${s[c]?'ON':'OFF'}`)}
      case 'warn':case 'warnings':case 'unwarn':case 'clearwarn':{let t=target(m,a);if(!t)return send(j,'Reply to a user or provide a number.');let k=j+':'+t,v=state.warnings.get(k)||0;if(c==='warn')v++;if(c==='unwarn')v=Math.max(0,v-1);if(c==='clearwarn')v=0;state.warnings.set(k,v);return send(j,`⚠️ @${numberOf(t)} warnings: ${v}`,{mentions:[t]})}
      case 'lock':case 'unlock':{if(!isGroup(j)||(!owner(u)&&!(await isAdmin(j,u))))return send(j,'Admin/owner only.');groupCfg(j).restricted=c==='lock';return send(j,`Restricted mode: ${groupCfg(j).restricted?'ON':'OFF'}`)}
      case 'rules':return send(j,groupCfg(j).rules);
      case 'setrules':{if(!isGroup(j)||(!owner(u)&&!(await isAdmin(j,u))))return send(j,'Admin/owner only.');groupCfg(j).rules=argText(body)||groupCfg(j).rules;return send(j,'✅ Rules saved.')}
      case 'modstatus':{let s=groupCfg(j);return send(j,`Anti-link ${s.antilink?'ON':'OFF'}\nAnti-spam ${s.antispam?'ON':'OFF'}\nRestricted ${s.restricted?'ON':'OFF'}`)}
      case 'linktest':return send(j,link(argText(body))?'🔗 Link detected':'✅ No link');
      case 'spamtest':return send(j,spam(argText(body))?'🚨 Spam pattern':'✅ No obvious spam');
      case 'audit':return send(j,state.audit.slice(-20).map(x=>`${x.t} ${x.a} ${x.j}`).join('\n')||'No audit events.');
      case 'banner':case 'image':case 'thumbnail':return banner(j,'✨ SIGMA 5');
      case 'activation':return state.sock.sendMessage(j,{image:fs.readFileSync(ASSETS.activation),caption:'🔗 SIGMA 5 activation asset'});
      case 'caption':return send(j,`SIGMA 5\n${argText(body)}`);
      case 'sticker':case 'mediahelp':case 'document':case 'audiohelp':case 'videohelp':case 'voicehelp':case 'gifhelp':case 'downloadhelp':return send(j,'Media helper active. Use WhatsApp media normally; no unauthorized scraping is included.');
      case 'fileinfo':return send(j,quoted(m)?'Quoted message found.':'Quote a file/media first.');
      case 'mimetype':return send(j,quoted(m)?'Quoted media found.':'No quoted media.');
      case 'choose':{let x=argText(body).split('|').map(x=>x.trim()).filter(Boolean);return send(j,x.length?x[Math.floor(Math.random()*x.length)]:'Usage: .choose a|b|c')}
      case 'coin':return send(j,Math.random()<.5?'🪙 Heads':'🪙 Tails');
      case '8ball':return send(j,['Yes.','No.','Maybe.','Ask later.'][Math.floor(Math.random()*4)]);
      case 'uuid':return send(j,crypto.randomUUID());
      case 'hash':return send(j,crypto.createHash('sha256').update(argText(body)).digest('hex'));
      case 'timestamp':{let n=Number(a[0]);return send(j,Number.isFinite(n)?new Date(n*1000).toISOString():'Usage: .timestamp <unix>')}
      case 'escape':return send(j,encodeURIComponent(argText(body)));
      case 'unescape':return send(j,decodeURIComponent(argText(body)));
      case 'url':try{return send(j,new URL(a[0]).toString())}catch{return send(j,'❌ Invalid URL')}
      case 'email':return send(j,/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(a[0]||'')?'✅ Valid':'❌ Invalid');
      case 'phone':return send(j,/^\d{7,15}$/.test(digits(a[0]||''))?'✅ Valid':'❌ Invalid');
      case 'color':return send(j,/^#[0-9a-f]{6}$/i.test(a[0]||'')?'✅ Valid':'❌ Invalid');
      case 'sanitize':return send(j,clean(argText(body)));
      case 'safetest':{let n=digits(a[0]||'');if(!n)return send(j,`Usage: ${cfg.prefix}safetest <number>`);return banner(j,`✅ SAFE TEST\n📱 +${n}\n🔐 Diagnostic only\n🚫 No payload, stress, spam or injection performed.`)}
      case 'diagnostics':return send(j,`Node ${process.version}\nWA ${state.sock?.user?'connected':'disconnected'}\nTelegram ${cfg.token?'configured':'missing'}\nCommands ${COMMANDS.length}`);
      case 'reload':return send(j,owner(u)?'✅ Registry loaded from commands.mjs. Restart to reload source edits.':'Owner only.');
      case 'save':return send(j,owner(u)?'✅ Baileys credentials are persisted automatically.':'Owner only.');
      case 'backup':return send(j,'Back up session/ privately. Never commit it.');
      case 'logs':return send(j,state.audit.slice(-10).map(x=>JSON.stringify(x)).join('\n')||'No logs.');
      case 'restart':return send(j,owner(u)?'Restart the Node process from your host/Termux.':'Owner only.');
      case 'shutdown':if(!owner(u))return send(j,'Owner only.');await send(j,'🛑 Shutting down.');process.exit(0);
      case 'broadcast':return send(j,owner(u)?'Broadcast is restricted to explicit owner-selected chats; no unsolicited mass broadcast is implemented.':'Owner only.');
      case 'setprefix':return send(j,'Edit PREFIX in .env and restart.');
      case 'allow':if(!owner(u))return send(j,'Owner only.');state.allow.add(digits(a[0]));return send(j,'✅ Added.');
      case 'deny':if(!owner(u))return send(j,'Owner only.');state.allow.delete(digits(a[0]));return send(j,'✅ Removed.');
      case 'allowlist':return send(j,owner(u)?[...state.allow].join('\n')||'Empty':'Owner only.');
      case 'maintenance':if(!owner(u))return send(j,'Owner only.');state.maintenance=!state.maintenance;return send(j,`Maintenance ${state.maintenance?'ON':'OFF'}`);
      case 'config':return send(j,`Owner: ${cfg.ownerName}\nPrefix: ${cfg.prefix}\nTelegram token: ${cfg.token?'configured':'missing'}\nChat ID: ${cfg.chatId?'configured':'missing'}`);
      case 'permissions':case 'security':return send(j,'Owner/admin checks • input validation • anti-link/anti-spam • no harmful payload injection.');
      case 'joke':return send(j,'Why did the developer go broke? Too many cache misses. 😄');
      case 'quote':return send(j,'Build carefully, test often, keep secrets private.');
      case 'fact':return send(j,'A byte contains eight bits.');
      case 'roast':return send(j,'Your code is so optimistic it compiles in your imagination. 😄');
      case 'compliment':return send(j,'You are building this one step at a time. ✨');
      case 'ship':case 'love':return send(j,`💫 Fun score: ${Math.floor(Math.random()*101)}%`);
      case 'rps':return send(j,['🪨 Rock','📄 Paper','✂️ Scissors'][Math.floor(Math.random()*3)]);
      case 'guess':return send(j,`🎯 Demo number: ${1+Math.floor(Math.random()*10)}`);
      case 'fortune':return send(j,'A small improvement today can save a big debugging session tomorrow.');
      case 'meme':return send(j,'WHEN IT WORKS FIRST TRY: suspicious. 😂');
      case 'anime':return send(j,'⚡ Anime mode activated.');
      case 'sigma':return send(j,'🐺 SIGMA 5 — powered by disciplined code.');
      case 'wolf':return send(j,'🐺 Stay connected. Stay powerful. Stay safe.');
      case 'neon':return banner(j,'🌈 SIGMA 5 • NEON MODE');
      default:return send(j,`❌ Unknown command: ${cfg.prefix}${c}\nUse ${cfg.prefix}menu to view the 150 available commands.`);
    }
  }catch(e){log.error({err:e,c},'command failed');return send(j,`❌ ${c} failed safely: ${e.message}`)}
}

async function connect(number=''){
  if(state.sock){try{state.sock.end(undefined)}catch{} state.sock=null;}
  const {state:auth,saveCreds}=await useMultiFileAuthState(path.join(ROOT,'session'));
  state.sock=makeWASocket({
    auth:{creds:auth.creds,keys:makeCacheableSignalKeyStore(auth.keys,log)},
    browser:Browsers.ubuntu('SIGMA 5'),logger:log,markOnlineOnConnect:false
  });
  state.sock.ev.on('creds.update',saveCreds);
  state.sock.ev.on('connection.update',async u=>{
    const {connection,lastDisconnect}=u;
    if(connection==='connecting'&&!auth.creds.registered&&number){
      try{
        const code=await state.sock.requestPairingCode(digits(number));
        console.log(`\n🔑 WhatsApp pairing code: ${code}\n`);
        if(state.telegram&&cfg.chatId){
          await state.telegram.telegram.sendPhoto(cfg.chatId,{source:ASSETS.activation},{caption:`🔗 SIGMA 5 • PAIRING CODE\n📱 +${digits(number)}\n🔑 ${code}\n\nWhatsApp → Linked Devices → Link with phone number`});
          await state.telegram.telegram.sendMessage(cfg.chatId,`🔑 WhatsApp pairing code: \`${code}\`\n\nEnter this code in WhatsApp → Linked Devices → Link with phone number.\n\n⏳ Waiting for WhatsApp connection...`,{parse_mode:'Markdown'});
        }
      }catch(e){log.error({err:e},'pairing failed')}
    }
    if(connection==='open'){
      console.log(`✅ WhatsApp connected: ${state.sock.user?.id||''}`);
      if(state.telegram&&cfg.chatId){
        await state.telegram.telegram.sendPhoto(cfg.chatId,{source:ASSETS.banner},{caption:'⭐ SIGMA 5 • WhatsApp Pairing SUCCESSFUL'});
        await state.telegram.telegram.sendMessage(cfg.chatId,`✅ WhatsApp connected successfully.\n📱 ${state.sock.user?.id||''}\n\nType /menu to view all 150 WhatsApp commands.`);
      }
    }
    if(connection==='close'){
      const code=new Boom(lastDisconnect?.error)?.output?.statusCode;
      if(code!==DisconnectReason.loggedOut)setTimeout(()=>connect(''),3000);else console.log('⚠️ Logged out. Remove session/ and pair again.');
    }
  });
  state.sock.ev.on('messages.upsert',async({messages})=>{
    for(const m of messages){
      if(!m.message||m.key.fromMe)continue;
      const body=textOf(m);
      if(await moderate(m,body))continue;
      await command(m);
    }
  });
}

async function telegramStart(){
  if(!cfg.token){console.log('ℹ️ Telegram controller disabled: TELEGRAM_BOT_TOKEN missing.');return}
  state.telegram=new Telegraf(cfg.token);
  state.telegram.use(async(ctx,next)=>{
    if(cfg.chatId&&String(ctx.chat?.id)!==String(cfg.chatId))return ctx.reply('⛔ Unauthorized control chat.');
    return next();
  });
  const homeKeyboard={inline_keyboard:[[{text:'🔗 Pair WhatsApp',callback_data:'PAIR_WA'},{text:'📋 Commands',callback_data:'WA_MENU'}],[{text:'📊 Status',callback_data:'WA_STATUS'}]]};
  const homeCaption='🐺 SIGMA 5\n\nWhatsApp + Telegram Control\n\n🔗 Pair your WhatsApp number to this bot.\n📱 Enter the WhatsApp number with country code.\n🔑 A WhatsApp pairing code will be generated and sent here.\n\n⚠️ This is a WhatsApp pairing code, not an SMS OTP.';
  state.telegram.start(async ctx=>{
    if(fs.existsSync(ASSETS.activation)) return ctx.replyWithPhoto({source:ASSETS.activation},{caption:homeCaption,reply_markup:homeKeyboard});
    return ctx.reply(homeCaption,{reply_markup:homeKeyboard});
  });
  state.telegram.action('WA_STATUS',async ctx=>{await ctx.answerCbQuery();return ctx.reply(`WhatsApp: ${state.sock?.user?'CONNECTED':'DISCONNECTED'}\nUptime: ${uptime()}`)});
  state.telegram.action('WA_MENU',async ctx=>{await ctx.answerCbQuery();for(const part of menuParts(3800))await ctx.reply(part);return});
  state.telegram.action('PAIR_WA',async ctx=>{
    await ctx.answerCbQuery();
    state.pairRequests.add(String(ctx.chat?.id||''));
    return ctx.reply('📱 Send your WhatsApp number with country code.\n\nExample: 919876543210\n\nA WhatsApp pairing code will then be sent to this Telegram chat.');
  });
  state.telegram.command('status',ctx=>ctx.reply(`WhatsApp: ${state.sock?.user?'CONNECTED':'DISCONNECTED'}\nUptime: ${uptime()}`));
  state.telegram.command('menu',async ctx=>{if(fs.existsSync(ASSETS.banner))await ctx.replyWithPhoto({source:ASSETS.banner},{caption:'🐺 SIGMA 5 • 150 WHATSAPP COMMANDS'});for(const part of menuParts(3800))await ctx.reply(part);return});
  state.telegram.on('text',async ctx=>{
    const chatId=String(ctx.chat?.id||'');
    if(!state.pairRequests.has(chatId))return;
    const raw=String(ctx.message?.text||'').trim();
    if(raw.startsWith('/'))return;
    const n=digits(raw);
    if(!n||n.length<7||n.length>15)return ctx.reply('❌ Invalid number. Send WhatsApp number with country code, for example: 919876543210');
    state.pairRequests.delete(chatId);
    if(state.sock?.user)return ctx.reply('✅ WhatsApp is already connected.');
    await connect(n);
    return ctx.reply('⏳ Pairing started. Wait for the WhatsApp pairing code in this Telegram chat, then enter it in WhatsApp → Linked Devices → Link with phone number.');
  });
  state.telegram.command('pair',async ctx=>{
    const n=digits(ctx.message.text.split(/\s+/)[1]||'');
    if(!n||n.length<7||n.length>15)return ctx.reply('❌ Usage: /pair <WhatsApp number with country code>\nExample: /pair 919876543210');
    if(state.sock?.user)return ctx.reply('✅ WhatsApp is already connected.');
    await connect(n);return ctx.reply('⏳ Pairing started. Wait for the WhatsApp pairing code in this Telegram chat, then enter it in WhatsApp → Linked Devices → Link with phone number.');
  });
  state.telegram.command('wa',async ctx=>{
    const p=ctx.message.text.split(/\s+/),to=p[1],text=p.slice(2).join(' ');
    if(!state.sock?.user)return ctx.reply('WhatsApp is not connected.');
    if(!to||!text)return ctx.reply('Usage: /wa <number or JID> <message>');
    try{await state.sock.sendMessage(to.includes('@')?to:`${digits(to)}@s.whatsapp.net`,{text:clean(text)});return ctx.reply('✅ Sent.')}catch(e){return ctx.reply(`❌ ${e.message}`)}
  });
  await state.telegram.launch();
  if(cfg.chatId&&fs.existsSync(ASSETS.activation)){
    try{
      await state.telegram.telegram.sendPhoto(cfg.chatId,{source:ASSETS.activation},{caption:homeCaption,reply_markup:homeKeyboard});
    }catch(e){log.warn({err:e},'startup banner could not be delivered to TELEGRAM_CHAT_ID')}
  }
  console.log('✅ Telegram controller started.');
}

async function main(){
  console.log(`\n🐺 SIGMA 5 • ${COMMANDS.length} commands`);
  await telegramStart();
  if(!cfg.token && !cfg.pairingNumber && !fs.existsSync(path.join(ROOT,'session','creds.json')))
    console.log('ℹ️ Configure .env or use Telegram /pair after starting the controller.');
  const hasSession=fs.existsSync(path.join(ROOT,'session','creds.json'));
  if(cfg.pairingNumber||hasSession) await connect(cfg.pairingNumber);
  else console.log('ℹ️ WhatsApp is waiting for Telegram Pair WhatsApp or /pair <number>.');
}
main().catch(e=>{log.error({err:e},'fatal');process.exit(1)});

